-- Temporary public demo content. Each row is deliberately a normal Studio item
-- and can be unpublished or deleted from /studio/.
INSERT OR IGNORE INTO content (id, type, status, category, project_id, title_tr, title_en, body_tr, body_en, created_at) VALUES
('a1d5f100-0001-4d01-8a01-000000000001', 'work', 'published', 'Photography', 'soft-ruins', 'Kırık Saatler', 'Broken Clocks', '<p>Gündelik zamanın yüzeyde bıraktığı küçük bozulmalar üzerine bir fotoğraf dizisi.</p><p>Seri: Yumuşak Harabeler.</p>', '<p>A photographic series about the small distortions that ordinary time leaves on a surface.</p><p>Series: Soft Ruins.</p>', '2026-09-18 12:00:00'),
('a1d5f100-0002-4d01-8a01-000000000002', 'work', 'published', 'Collages', 'soft-ruins', 'İnce Sesler', 'Thin Noises', '<p>Kesilmiş yüzeyler, tekrarlanan çizgiler ve kaybolmaya yüz tutmuş sesler üzerine bir kolaj çalışması.</p>', '<p>A collage work on cut surfaces, repeated lines and sounds on the verge of disappearing.</p>', '2026-08-02 12:00:00'),
('a1d5f100-0003-4d01-8a01-000000000003', 'work', 'published', 'Drawings', 'soft-ruins', 'Kendi Kendine', 'To Itself', '<p>Karakterin kendi iç sesiyle kurduğu kırılgan ilişkiye dair çizimler.</p>', '<p>Drawings about a character''s fragile relationship with its own inner voice.</p>', '2025-11-15 12:00:00'),
('a1d5f100-0004-4d01-8a01-000000000004', 'work', 'published', 'Films', 'soft-ruins', 'Kısa Devre', 'Short Circuit', '<p>Hafızanın bir anda kesilmesi ve görüntünün geri dönmesi üzerine kısa film denemesi.</p>', '<p>A short film experiment on memory suddenly cutting out and the image returning.</p>', '2025-06-16 12:00:00'),
('a1d5f100-0005-4d01-8a01-000000000005', 'work', 'published', 'Video art', 'soft-ruins', 'Daha Yüksek', 'Louder', '<p>Tekrar eden hareketin ve sesin bedende bıraktığı iz üzerine video çalışması.</p>', '<p>A video work about the trace that repeated motion and sound leave in the body.</p>', '2024-10-09 12:00:00'),
('b1d5f100-0001-4d01-8a01-000000000001', 'post', 'published', NULL, NULL, 'Punk, arşiv ve tekrar', 'Punk, archive, repetition', '<p>Ses çoğu zaman görüntüden önce hafızaya yerleşir. Bir ritim, bir kırılma, tekrar eden bir kelime: imgenin taşımadığı türden bir iz bırakır.</p><p>Punk benim için yalnızca bir müzik türü değil; kusuru saklamayan, tekrarın içinde direnç bulan bir çalışma biçimi.</p><p>Arşiv, yalnızca geçmişe bakmak değildir. Tekrar bakmanın; kesmenin ve yeni bir bağlam kurmanın da yoludur.</p>', '<p>Sound often settles into memory before the image does. A rhythm, a break, a repeated word: it leaves a mark unlike the one carried by an image.</p><p>For me, punk is not only a genre of music; it is a way of working that does not hide its flaws and finds resistance in repetition.</p><p>An archive is not only about looking back. It is also a way to look again, to cut, and to build a new context.</p>', '2026-09-18 12:00:00'),
('b1d5f100-0002-4d01-8a01-000000000002', 'post', 'published', NULL, NULL, 'Stüdyoda bir gün', 'A day in the studio', '<p>Yüzey, boya ve beklemenin gün boyunca birbirine karıştığı kısa bir stüdyo günlüğü.</p>', '<p>A short studio diary where surface, paint and waiting mingle through the day.</p>', '2026-08-02 12:00:00'),
('b1d5f100-0003-4d01-8a01-000000000003', 'post', 'published', NULL, NULL, 'Kesmek ve yeniden bakmak', 'Cutting and looking again', '<p>Kolajın bir düşünme biçimi, yeniden bakmanın da üretim pratiği olması üzerine notlar.</p>', '<p>Notes on collage as a way of thinking and looking again as a making practice.</p>', '2026-06-16 12:00:00');
